///
/// EXPERIMENTAL: Embedder-provided key-encryption-key source. The callback runs
/// synchronously on the thread calling profile create/unlock, outside the
/// profile lifecycle mutex. The profile never retains the source. Password and
/// OS-keyring sources are built-in mechanisms; this interface supplies another
/// explicit source, not a fallback when a built-in source fails.
/// Native C callers transfer a counted reference for each refptr argument, as
/// with other CEF interfaces; the C++ wrapper handles that transfer automatically.
///
/*--cef(source=client,added=experimental)--*/
class AlloyKeySource : public virtual CefBaseRefCounted {
 public:
  ///
  /// Derive a 256-bit key from the profile's public random |salt|. |salt_size|
  /// and |key_size| are both 32. Write exactly |key_size| bytes to |key| and
  /// return true on success. Buffers are borrowed for this call only and must
  /// not be retained. Alloy wipes its output buffer after use. The embedder
  /// owns clearing its own credentials and any key copies. Return false for
  /// cancellation or failure. No private site/profile metadata is in |salt|.
  ///
  /*--cef()--*/
  virtual bool DeriveKey(const void* salt, size_t salt_size,
                         void* key, size_t key_size) = 0;
};

///
/// EXPERIMENTAL: An encrypted profile lifecycle, usable before CefInitialize.
/// These methods perform blocking crypto/filesystem work; call them on an
/// embedder background thread. The library uses one authenticated catalogue and
/// encrypted file layer for all profile/record state. Store/browser-context
/// binding is separate. Releasing the last reference locks and wipes the profile.
///
/*--cef(source=library,added=experimental)--*/
class AlloyProfile : public virtual CefBaseRefCounted {
 public:
  ///
  /// Unlock a password profile. The password is UTF-8 encoded for Argon2id;
  /// Alloy retains no password after the call. The embedder owns clearing its
  /// input string. Returns false for wrong credentials, corruption or I/O
  /// failure. Failure never creates a fresh profile or selects another source.
  ///
  /*--cef()--*/
  virtual bool UnlockWithPassword(const CefString& password) = 0;

  ///
  /// Unlock an external-source profile using |source|. The source must derive
  /// the same key for the stored salt used at creation. Returns false on failure.
  ///
  /*--cef()--*/
  virtual bool UnlockWithKeySource(CefRefPtr<AlloyKeySource> source) = 0;

  ///
  /// Flush completed writes, lock and wipe keys. Returns true only when this
  /// synchronous lock completed successfully. During an in-flight unlock it
  /// requests cancellation and returns false; state remains TRANSITION until
  /// that operation has wiped its keys. Retry after the operation completes.
  ///
  /*--cef()--*/
  virtual bool Lock() = 0;

  ///
  /// Return the current state. LOCKED means no profile keys or admitted record
  /// access remain; TRANSITION is not a successful lock acknowledgement.
  ///
  /*--cef(default_retval=ALLOY_PROFILE_ERROR)--*/
  virtual alloy_profile_state_t GetState() = 0;
};

///
/// EXPERIMENTAL: Create and unlock a new password profile at |path|. Existing
/// paths are refused. The password derives a KEK which wraps a fresh random
/// profile key; it is not used as a file/record key. Returns NULL on failure.
/// Call on an embedder background thread; CefInitialize is not required.
///
/*--cef(added=experimental)--*/
CefRefPtr<AlloyProfile> AlloyCreateProfile(const CefString& path,
                                         const CefString& password);

///
/// EXPERIMENTAL: Create and unlock a new profile using an explicit external
/// |source|. Existing paths are refused. Returns NULL on failure.
///
/*--cef(added=experimental)--*/
CefRefPtr<AlloyProfile> AlloyCreateProfileWithKeySource(
    const CefString& path, CefRefPtr<AlloyKeySource> source);

///
/// EXPERIMENTAL: Open an existing profile while locked. Only public bootstrap
/// framing/parameters are read. No private metadata or records are decrypted.
/// Returns NULL if the profile cannot be opened; never creates or repairs it.
///
/*--cef(added=experimental)--*/
CefRefPtr<AlloyProfile> AlloyOpenProfile(const CefString& path);
